import { supabase } from './client.js'

// Inserts a feedback submission. id and created_at are generated by the
// database, so they are never sent from the client. `other_type` is only
// populated when the selected type is "Other".
export async function submitFeedback({ type, otherType, name, email, message }) {
  if (!supabase) {
    throw new Error(
      'Feedback isn’t configured yet. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY.',
    )
  }

  const { error } = await supabase.from('feedback_submissions').insert({
    type,
    other_type: type === 'Other' ? otherType?.trim() || null : null,
    name: name?.trim() || null,
    email: email?.trim() || null,
    message: message.trim(),
  })

  if (error) throw error
}
